<label class="form-label col-md-6">Descrição<input class="form-control" name="description" value="{{ $transaction?->description }}" maxlength="255" required></label><label class="form-label col-md-3">Tipo<select class="form-select" name="type"><option value="income" @selected($transaction?->type==='income')>Receita</option><option value="expense" @selected($transaction?->type==='expense')>Despesa</option></select></label><label class="form-label col-md-3">Valor<input class="form-control" name="amount" type="number" step="0.01" min="0.01" value="{{ $transaction?->amount }}" required></label><label class="form-label col-md-4">Vencimento<input class="form-control" name="due_date" type="date" value="{{ $transaction?->due_date?->format('Y-m-d') }}" required></label><label class="form-label col-md-4">Estado<select class="form-select" name="status">@foreach(['pending'=>'Pendente','paid'=>'Pago','cancelled'=>'Cancelado'] as $key=>$label)<option value="{{ $key }}" @selected($transaction?->status===$key)>{{ $label }}</option>@endforeach</select></label><label class="form-label col-md-4">Cliente / fornecedor<input class="form-control" name="counterparty" value="{{ $transaction?->counterparty }}"></label>